import os
from flask import Flask, request, jsonify, render_template_string, send_from_directory
from groq import Groq
app = Flask(__name__)
client = Groq(api_key=os.environ.get("GROQ_API_KEY"))
HTML_PAGE = """<!DOCTYPE html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>LUMI AI</title><style>body{margin:0;font-family:sans-serif;background:#0f0f0f;color:#fff;display:flex;flex-direction:column;height:100vh}.header{padding:15px;background:#1a1a1a;text-align:center;border-bottom:1px solid #333}#chat{flex:1;overflow-y:auto;padding:20px;position:relative}#watermark{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);opacity:0.07;pointer-events:none;z-index:0}#watermark img{width:280px}.messages{position:relative;z-index:1}.msg{margin:12px 0;padding:12px 16px;border-radius:18px;max-width:80%;line-height:1.5}.user{background:#2e7d32;margin-left:auto}.ai{background:#2a2a2a}#suggestions{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin:20px 0;position:relative;z-index:1}.sug{border:1px solid #444;padding:12px 16px;border-radius:12px;background:#1e1e1e;cursor:pointer}.sug:hover{background:#333}#inputArea{display:flex;padding:12px;background:#1a1a1a;gap:10px}#inputArea input{flex:1;padding:14px;border-radius:24px;border:1px solid #444;background:#2a2a2a;color:white}#inputArea button{padding:14px 22px;border-radius:24px;border:none;background:#4caf50;color:white;font-weight:bold}#adModal{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.92);z-index:9999;justify-content:center;align-items:center}.box{background:white;color:black;padding:30px;border-radius:20px;text-align:center;width:90%;max-width:360px}#limit{font-size:12px;color:#aaa;margin-top:5px}</style></head><body><div class='header'><h2 style='margin:0'>LUMI AI</h2><div id='limit'>Free: 0/5</div></div><div id='chat'><div id='watermark'><img src='/logo.png'></div><div id='suggestions'><div class='sug' onclick="setText('Create a project plan for LUMI AI')">📁 Create project</div><div class='sug' onclick="setText('Explain this code for me')">💻 Explain code</div><div class='sug' onclick="setText('Write an essay about AI in Nigeria')">✍️ Write essay</div><div class='sug' onclick="setText('Give me a business idea for students')">💡 Business idea</div></div><div class='messages' id='messages'></div></div><div id='inputArea'><input id='userInput' placeholder='Ask LUMI anything...'><button onclick='send()'>Send</button></div><div id='adModal'><div class='box'><h3>🎉 Free Limit Reached!</h3><p>You used 5 free searches.</p><p>Watch ad to get 5 more free!</p><div style='background:#f0f0f0;padding:25px;margin:15px 0;border-radius:10px'>MONETAG AD HERE</div><button onclick='watchAd()' style='background:#4caf50;color:white;padding:14px;border:none;border-radius:10px;width:100%;font-weight:bold'>Watch Ad & Continue</button></div></div><script>let searches=parseInt(localStorage.getItem('lumi_search')||'0');let maxFree=5;function updateLimit(){document.getElementById('limit').innerText='Free: '+searches+'/'+maxFree}updateLimit();function setText(t){document.getElementById('userInput').value=t;document.getElementById('userInput').focus()}function checkLimit(){if(searches>=maxFree){document.getElementById('adModal').style.display='flex';return false}return true}function watchAd(){alert('Playing Monetag Ad...');searches=0;localStorage.setItem('lumi_search','0');updateLimit();document.getElementById('adModal').style.display='none';}async function send(){if(!checkLimit())return;let input=document.getElementById('userInput');let text=input.value.trim();if(!text)return;document.getElementById('suggestions').style.display='none';let box=document.getElementById('messages');box.innerHTML+=`<div class='msg user'>${text}</div>`;input.value='';searches++;localStorage.setItem('lumi_search',searches);updateLimit();box.innerHTML+=`<div class='msg ai' id='thinking'>Thinking...</div>`;document.getElementById('chat').scrollTop=document.getElementById('chat').scrollHeight;try{let r=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text})});let d=await r.json();document.getElementById('thinking').remove();box.innerHTML+=`<div class='msg ai'>${d.reply}</div>`;}catch(e){document.getElementById('thinking').remove();box.innerHTML+=`<div class='msg ai'>Error, try again</div>`}document.getElementById('chat').scrollTop=document.getElementById('chat').scrollHeight;if(searches>=maxFree){setTimeout(()=>{document.getElementById('adModal').style.display='flex'},500)}}document.getElementById('userInput').addEventListener('keypress',e=>{if(e.key==='Enter')send()})</script></body></html>"""
@app.route('/')
def home(): return render_template_string(HTML_PAGE)
@app.route('/logo.png')
def logo(): return send_from_directory('.', 'logo.png')
@app.route('/chat', methods=['POST'])
def chat():
    msg=request.json.get('message','')
    comp=client.chat.completions.create(model="llama-3.1-8b-instant",messages=[{"role":"user","content":msg}])
    return jsonify({"reply":comp.choices[0].message.content})
if __name__=='__main__': app.run(host='0.0.0.0',port=10000)